let seasonReviewYear=null,seasonTransitionBusy=false,seasonReviewReturn=null;
function seasonReviewMoney(n){return (n<0?'−':'')+'£'+Math.abs(n).toLocaleString('ko-KR');}
function seasonReviewMarkup(m){
 const esc=escapeText,l=m.league,p=m.players,f=m.finance;
 const leaders=[['구단 최다 득점',p.goals,'골'],['구단 최다 도움',p.assists,'도움'],['가장 많이 뛴 선수',p.minutes,'분'],['골키퍼 무실점',p.cleanSheets,'경기']];
 return `${typeof ClubArt==='undefined'?'':'<div class="season-review-art">'+ClubArt.html(ClubArt.seasonScene(m))+'</div>'}<div class="season-review-heading"><div><span class="eyebrow">OUR SEASON</span><h3>${m.year}시즌 · ${m.division}부 ${m.rank?m.rank+'위':'첫 경기 준비'}</h3></div><span>${m.final?'시즌 완료':'진행 중 · 확정 기록'}</span></div><div class="season-review-kpis"><div><span>리그 승점</span><strong>${m.points}</strong></div><div><span>${l.partial?'남아 있는 리그 기록':'리그 경기'}</span><strong>${l.played}<small> / ${l.total}</small></strong></div><div><span>승 · 무 · 패</span><strong>${l.won} · ${l.drawn} · ${l.lost}</strong></div><div><span>득점 · 실점</span><strong>${l.gf} · ${l.ga}</strong></div></div>${l.partial?'<p class="season-review-note">이전 저장에 남은 경기만 합산했습니다. 최종 순위와 승점은 당시 시즌 기록입니다.</p>':''}<div class="season-review-titles"><p>리그 우승 · ${esc(l.champion||'아직 결정되지 않음')}</p>${m.cups.map(c=>`<p>${c.competition==='cup'?'국내컵':'유럽 대회'} · ${c.wonTitle?'우리 구단 우승':c.champion?'우승 '+esc(c.champion):m.current?'현재 우승 기록 없음':'우승 기록 없음'}<small>우리 구단 기록 ${c.matches}경기</small></p>`).join('')}</div><h4>시즌을 만든 선수들</h4>${p.partial?'<p class="season-review-note">선수 기록은 저장에 남은 경기·득점부터 집계합니다. 승부차기 득점은 제외합니다.</p>':''}<div class="season-review-leaders">${leaders.map(([label,row,unit])=>`<article><span>${label}</span><strong>${row.players.length?row.players.map(x=>esc(x.name)).join(' · '):'기록 대기'}</strong><small>${row.value?row.value.toLocaleString('ko-KR')+unit+(row.players.length>1?' · 공동 기록':''):'확정 기록 없음'}</small></article>`).join('')}</div>${m.growth.length?`<details><summary>이번 시즌 선수 성장 ${m.growth.length}명</summary><ul>${m.growth.map(x=>`<li><span>${esc(x.name)} · ${x.pos}</span><strong>주요 능력 +${x.gain}</strong></li>`).join('')}</ul><p class="season-review-note">현재 선수의 이번 시즌 등록 당시와 비교합니다. 지난 시즌의 능력 변화는 추정하지 않습니다.</p></details>`:''}<details><summary>구단 자금 결산${f.known?' · '+seasonReviewMoney(f.net):''}</summary>${f.known?`<dl class="season-review-finance"><div><dt>${f.partial?'기록 시작 자금':'시즌 시작 자금'}</dt><dd>${seasonReviewMoney(f.opening)}</dd></div>${f.groups.map(g=>`<div><dt>${esc(g.label)}</dt><dd>${seasonReviewMoney(g.amount)}</dd></div>`).join('')}<div><dt>${m.final?'시즌 종료 자금':'현재 자금'}</dt><dd>${seasonReviewMoney(f.closing)}</dd></div></dl><p class="season-review-note">거래 장부의 순증감을 합산합니다. 리그 경기 순수익은 선수 급여 차감 후 금액이며, 코치 급여는 별도입니다.${f.partial?' 이전 저장에 남은 거래부터 표시합니다.':''}</p>`:'<p class="season-review-note">이 시즌의 재정 장부가 저장에 남아 있지 않습니다.</p>'}</details>`;
}
function renderSeasonReview(){
 if(view!=='cup')return;const host=$('season-review-panel');if(!host)return;
 const years=SeasonReview.years(season);if(!years.includes(seasonReviewYear))seasonReviewYear=season.year;
 const m=SeasonReview.read(season,seasonReviewYear);
 host.innerHTML=`<section class="season-review-card" aria-labelledby="season-review-title"><div class="season-review-heading"><h2 id="season-review-title">우리 구단 시즌 결산</h2><label>시즌 <select id="season-review-year" aria-label="결산 시즌 선택">${years.map(y=>`<option value="${y}"${y===m.year?' selected':''}>${y}시즌${y===season.year?' · 현재':''}</option>`).join('')}</select></label></div>${seasonReviewMarkup(m)}<button type="button" id="review-match-history" class="secondary">${m.year}시즌 경기 기록 보기</button>${m.next?'<button type="button" id="review-next-season" class="primary">다음 시즌 계획 확인</button>':''}</section>`;
 $('season-review-year').onchange=e=>{seasonReviewYear=Number(e.target.value);renderSeasonReview();$('season-review-year').focus({preventScroll:true});};
 $('review-match-history').onclick=()=>openMatchArchive(null,m.year);
 const next=$('review-next-season');if(next)next.onclick=()=>openSeasonReview(next);
}
function openSeasonReview(trigger){
 if(seasonTransitionBusy)return;const dialog=$('season-review-dialog');if(!dialog)return;
 const m=SeasonReview.read(season);if(!m.next){notify('리그·컵·유럽 대회를 모두 마친 뒤 다음 시즌을 준비할 수 있어요.');return;}
 seasonReviewReturn=trigger||document.activeElement;
 dialog.innerHTML=`<div class="season-review-dialog-head"><div><span class="eyebrow">THE NEXT CHAPTER</span><h2 id="season-transition-title">${m.year}시즌을 돌아보며</h2></div><button id="close-season-review" class="secondary" aria-label="시즌 결산 닫기">×</button></div><div class="season-review-dialog-body">${seasonReviewMarkup(m)}<section class="season-transition-plan" aria-labelledby="season-transition-plan-title"><h3 id="season-transition-plan-title">${m.next.year}시즌 · ${m.next.division}부에서 다시 시작</h3><p>${m.next.europe?'챔피언스리그 출전권을 확보했습니다.':'다음 시즌 유럽 대회 출전권은 없습니다. 1부 2위 이내에 도전하세요.'}</p><ul><li>선수 능력·경험, 보유 선수와 코치 계약, 자금 ${seasonReviewMoney(m.next.balance)}을 이어갑니다.</li><li>체력은 100으로, 부상은 회복됩니다.${m.next.suspensionsReset?' 누적 경고와 남은 출전 정지는 초기화됩니다.':''}</li><li>새 리그·컵 일정과 유소년 탐색·시즌 과제로 시작합니다.</li><li>지난 성적과 선수 기록은 대회 → 시즌 결산에서 다시 볼 수 있습니다.</li></ul></section><p id="season-transition-status" role="status"></p><button id="confirm-next-season" class="primary">${m.next.year}시즌 시작하기</button></div>`;
 const close=()=>{if(seasonTransitionBusy)return;dialog.close();seasonReviewReturn?.focus?.({preventScroll:true});};
 $('close-season-review').onclick=close;dialog.oncancel=e=>{e.preventDefault();close();};
 $('confirm-next-season').onclick=()=>{
  if(seasonTransitionBusy)return;seasonTransitionBusy=true;const year=season.year,button=$('confirm-next-season');button.disabled=true;$('close-season-review').disabled=true;$('season-transition-status').textContent='새 시즌 일정과 선수단을 준비하고 있습니다…';
  requestAnimationFrame(()=>setTimeout(()=>{try{if(season.year!==year||!S.ready(season))throw Error('시즌이 변경되었습니다. 결산을 다시 열어 주세요.');const next=S.nextSeason(season);season=next;state=next.match;selected=null;rotationNote='';seasonReviewYear=next.year;view='club';save();dialog.close();$('notice').hidden=true;render();window.scrollTo({top:0,behavior:'instant'});$('mobile-match-action')?.focus({preventScroll:true});}catch(error){$('season-transition-status').textContent='새 시즌을 준비하지 못했습니다. '+error.message;button.disabled=false;$('close-season-review').disabled=false;}finally{seasonTransitionBusy=false;}},0));
 };
 if(!dialog.open)dialog.showModal();$('close-season-review').focus({preventScroll:true});
}
